            hold.holdAgent(), hold.reviewAgent(), hold.releaseAgent(),
            hold.heldAt().toString(),
            hold.reviewedAt() == null ? null : hold.reviewedAt().toString(),
            hold.releasedAt() == null ? null : hold.releasedAt().toString());
}

